// Ins stages a new row, with a setter for every insertable column. A column
// left unset is absent from the statement, so the database default applies;
// a zero value that was set is written.
type Ins struct {
	row Row
	set uint64

	// conflict is the upsert target, as a bit per unique-constraint
	// column set. Zero means a plain insert, and a duplicate is an error
	// — which is the right default: silently updating a row you meant to
	// create is a data-loss bug that looks like success.
	conflict uint8

	// add marks the assigned columns an upsert ACCUMULATES into rather
	// than overwrites. Part of the statement key, beside the mask.
	add uint64
}

// Create stages a new row.
func Create() Ins { return Ins{} }

// Assigned reports the mask, which is also the statement key.
func (n Ins) Assigned() uint64 { return n.set }

// insertArgs appends the values n assigns, in column order.
func (n *Ins) insertArgs(args []any) []any {
	for i := 0; i < nInsertable; i++ {
		if n.set&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, n.row.ID)
		case 1:
			args = append(args, n.row.AccountID)
		case 2:
			args = append(args, n.row.Region)
		case 3:
			args = append(args, n.row.Name)
		case 4:
			args = append(args, n.row.Environment)
		case 5:
			args = append(args, n.row.TargetGroup)
		case 6:
			args = append(args, n.row.TargetName)
		case 7:
			args = append(args, n.row.Port)
		case 8:
			args = append(args, n.row.Balancer)
		case 9:
			args = append(args, n.row.Template.OrNull())
		case 10:
			args = append(args, n.row.MinSize)
		case 11:
			args = append(args, n.row.MaxSize)
		case 12:
			args = append(args, n.row.CostCap)
		case 13:
			args = append(args, n.row.AddWait)
		case 14:
			args = append(args, n.row.RemoveWait)
		case 15:
			args = append(args, n.row.Rules.OrNull())
		case 16:
			args = append(args, n.row.Mode)
		case 17:
			args = append(args, n.row.AutoBy)
		case 18:
			args = append(args, n.row.AutoAt.Arg())
		case 19:
			args = append(args, n.row.State)
		case 20:
			args = append(args, n.row.PausedReason)
		case 21:
			args = append(args, n.row.Note)
		case 22:
			args = append(args, n.row.EnrollBase)
		case 23:
			args = append(args, n.row.FailedStarts)
		case 24:
			args = append(args, n.row.LastAddAt.Arg())
		case 25:
			args = append(args, n.row.LastRemoveAt.Arg())
		case 26:
			args = append(args, n.row.CheckedAt.Arg())
		case 27:
			args = append(args, n.row.CreatedBy)
		case 28:
			args = append(args, n.row.CreatedAt)
		case 29:
			args = append(args, n.row.AwsTrack.OrNull())
		case 30:
			args = append(args, n.row.AwsGroup)
		case 31:
			args = append(args, n.row.AwsTemplate)
		case 32:
			args = append(args, n.row.AwsNote)
		case 33:
			args = append(args, n.row.AwsTriedAt.Arg())
		}
	}
	return args
}

